<?php declare(strict_types=1); ?>
<div class="ap-grid"><section class="ap-stack"><?php foreach($batches as$b): ?><article class="ap-card"><header><div><strong><?= h($b['batch_number']) ?></strong><small><?= h(date_us($b['execution_date'])) ?> · <?= h(status_label($b['payment_method'])) ?></small></div><?= badge($b['status']) ?></header><dl><div><dt>Gross</dt><dd><?= money($b['gross_amount']) ?></dd></div><div><dt>Credits</dt><dd><?= money($b['credit_amount']) ?></dd></div><div><dt>Net</dt><dd><?= money($b['net_amount']) ?></dd></div></dl><a class="mini-button primary" href="?tab=batches&batch=<?= (int)$b['id'] ?>">Open batch</a></article><?php endforeach; ?><?php if(!$batches): render_empty_state('No payment batches','Prepare a batch with independent reviewer and approver assignments.'); endif; ?>
<article class="panel"><header class="panel-head"><div><span class="eyebrow">New payment batch</span><h2>Prepare controlled batch</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="create_batch"><label><span>Company</span><select name="company_id"><?= company_options($company) ?></select></label><label><span>Execution date</span><input type="date" name="execution_date" value="<?= date('Y-m-d',strtotime('+3 days')) ?>"></label><label><span>Payment method</span><select name="payment_method"><?php foreach(accounts_payable_payment_methods()as$m): ?><option value="<?= h($m) ?>"><?= h(status_label($m)) ?></option><?php endforeach; ?></select></label><label><span>Bank / adapter reference</span><input name="bank_account_reference" value="PAYMENT-VAULT-REFERENCE" required></label><label><span>Preparer</span><select name="prepared_by"><?= user_options($owner) ?></select></label><label><span>Reviewer</span><select name="reviewed_by"><?= user_options($reviewer) ?></select></label><label><span>Approver</span><select name="approved_by"><?= user_options($approver) ?></select></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Batch prepared from approved invoices with controlled payment references and independent review assignments.</textarea></label><?php if(can('accounts_payable.create')): ?><button class="button primary span-2">Create batch</button><?php endif; ?></form></article></section>
<aside class="ap-stack"><?php if($batch): ?><article class="panel"><header class="panel-head"><div><span class="eyebrow">Payment batch</span><h2><?= h($batch['batch_number']) ?></h2></div><?= badge($batch['status']) ?></header><p><?= h(data_company_name($batch['company_id'])) ?> · Net <?= money($batch['net_amount']) ?></p>
<?php foreach($batchItems as$item): $i=fulfillment_find_invoice((int)$item['invoice_id']); ?><div class="ap-card"><strong><?= h($i['invoice_number']??'Invoice') ?></strong><p><?= h(data_supplier_name($item['supplier_id'])) ?></p><b><?= money($item['net_amount']) ?></b></div><?php endforeach; ?>
<?php if($batch['status']==='draft'&&can('accounts_payable.edit')): ?><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="add_batch_item"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><label class="span-2"><span>Approved invoice</span><select name="invoice_id"><?php foreach(accounts_payable_eligible_invoices()as$i): if(!in_array(fulfillment_invoice_effective_status($i),['approved_for_payment','partially_paid'],true)||(int)$i['company_id']!==(int)$batch['company_id'])continue; ?><option value="<?= (int)$i['id'] ?>"><?= h($i['invoice_number'].' · '.data_supplier_name($i['supplier_id']).' · '.money($i['total_amount'])) ?></option><?php endforeach; ?></select></label><label class="span-2"><span>Invoice amount to apply</span><input type="number" min="0.01" step="0.01" name="payment_amount" placeholder="Leave blank for full outstanding balance"></label><label class="span-2"><span>Optional supplier credit</span><select name="credit_id"><option value="0">No credit</option><?php foreach($credits as$c): if((int)$c['company_id']!==(int)$batch['company_id']||!in_array($c['status'],['validated','partial'],true))continue; ?><option value="<?= (int)$c['id'] ?>"><?= h($c['credit_number'].' · '.data_supplier_name($c['supplier_id']).' · '.money($c['remaining_amount'])) ?></option><?php endforeach; ?></select></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Invoice and optional supplier credit verified for this payment batch.</textarea></label><button class="button secondary span-2">Add invoice</button></form><?php endif; ?>
<div class="modal-actions"><?php foreach(['reviewed'=>'Review','approved'=>'Approve','released'=>'Release']as$target=>$label): if((($target==='reviewed'&&$batch['status']==='draft'&&can('accounts_payable.review'))||($target==='approved'&&$batch['status']==='reviewed'&&can('accounts_payable.approve'))||($target==='released'&&$batch['status']==='approved'&&can('accounts_payable.execute')))): ?><form method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="transition_batch"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><input type="hidden" name="target_status" value="<?= h($target) ?>"><input type="hidden" name="evidence_note" value="Independent <?= h(strtolower($label)) ?> completed after verification of batch totals, invoices, credits, payment instructions, and role separation."><button class="button <?= $target==='released'?'primary':'secondary' ?>"><?= h($label) ?></button></form><?php endif; endforeach; ?></div></article>
<?php if(in_array($batch['status'],['released','transmitted','accepted','failed','returned'],true)&&can('accounts_payable.execute')): ?><article class="panel"><header class="panel-head"><div><span class="eyebrow">External execution evidence</span><h2>Record provider status</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="record_execution"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><label><span>Status</span><select name="execution_status"><?php foreach(['transmitted','accepted','settled','failed','returned']as$s): ?><option value="<?= h($s) ?>"><?= h(status_label($s)) ?></option><?php endforeach; ?></select></label><label><span>Fee</span><input type="number" min="0" step="0.01" name="fee_amount" value="0"></label><label><span>Provider reference</span><input name="provider_reference" required></label><label><span>Settlement reference</span><input name="settlement_reference"></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Manual provider acknowledgment recorded; no autonomous bank transmission occurred.</textarea></label><button class="button primary span-2">Record execution evidence</button></form></article><?php endif; ?>
<?php if($batch['status']==='settled'&&can('accounts_payable.reconcile')): $execution=$executions[0]??null; ?><article class="panel"><header class="panel-head"><div><span class="eyebrow">Independent reconciliation</span><h2>Reconcile settlement</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="reconcile"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><input type="hidden" name="execution_id" value="<?= (int)($execution['id']??0) ?>"><label><span>Settled amount</span><input type="number" step="0.01" name="settled_amount" value="<?= h((string)$batch['net_amount']) ?>"></label><label><span>Fee amount</span><input type="number" step="0.01" name="fee_amount" value="<?= h((string)($execution['fee_amount']??0)) ?>"></label><label><span>Bank reference</span><input name="bank_reference" required></label><label><span>Reviewer</span><select name="reviewer_id"><?= user_options($reviewer) ?></select></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Bank settlement, provider acknowledgment, batch total, and payment fees independently reconciled.</textarea></label><button class="button primary span-2">Complete reconciliation</button></form></article><?php endif; ?>
<?php else: ?><article class="panel"><header class="panel-head"><div><span class="eyebrow">Batch details</span><h2>Select a payment batch</h2></div></header><p>Open a batch to add invoices, complete dual control, record settlement, and reconcile the payment.</p></article><?php endif; ?></aside></div>

